// OrderService — places an order
class OrderService {
  async placeOrder(cmd: PlaceOrderCommand): Promise<Order> {
    // Write to DB
    const order = await this.db.query(
      'INSERT INTO orders (customer_id, status) VALUES ($1, $2) RETURNING *',
      [cmd.customerId, 'pending']
    );

    // Publish event directly to Kafka
    await this.kafka.producer.send({
      topic: 'order-events',
      messages: [{ value: JSON.stringify({ type: 'OrderPlaced', orderId: order.id }) }]
    });

    return order;
  }
}

// InventoryService — consumes OrderPlaced and reserves stock
class InventoryConsumer {
  async onOrderPlaced(event: OrderPlacedEvent): Promise<void> {
    // Reserve the stock
    await this.db.query(
      'UPDATE inventory SET reserved = reserved + $1 WHERE product_id = $2',
      [event.quantity, event.productId]
    );

    // Record that we processed this event (separate transaction)
    await this.db.query(
      'INSERT INTO processed_events (event_id) VALUES ($1)',
      [event.id]
    );
  }
}

