-- Outbox table schema
CREATE TABLE outbox (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  aggregate_type TEXT NOT NULL,         -- e.g. 'order'
  aggregate_id  TEXT NOT NULL,          -- orderId — used as Kafka partition key
  event_type    TEXT NOT NULL,          -- e.g. 'OrderPlaced'
  payload       JSONB NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  published_at  TIMESTAMPTZ           -- NULL = not yet relayed
);
CREATE INDEX outbox_unpublished ON outbox (aggregate_id, created_at) WHERE published_at IS NULL;

-- Service write (single transaction)
BEGIN;
INSERT INTO orders (id, customer_id, status) VALUES ($1, $2, 'pending');
INSERT INTO outbox (aggregate_type, aggregate_id, event_type, payload)
  VALUES ('order', $1, 'OrderPlaced', '{"orderId": $1, "customerId": $2}');
COMMIT;

-- Relay logic (polling)
async function relayLoop() {
  while (true) {
    const rows = await db.query(
      'SELECT * FROM outbox WHERE published_at IS NULL ORDER BY aggregate_id, created_at LIMIT 100'
    );
    for (const row of rows) {
      await kafka.producer.send({
        topic: 'order-events',
        messages: [{ key: row.aggregate_id, value: JSON.stringify(row.payload) }]
      });
      await db.query('UPDATE outbox SET published_at = NOW() WHERE id = $1', [row.id]);
    }
    await sleep(500); // poll interval
  }
}

// CDC alternative (Debezium):
// Configure Debezium connector to watch the outbox table.
// Debezium reads INSERT events from the PostgreSQL WAL and publishes them to Kafka directly.
// No polling — events appear in Kafka within milliseconds of the DB commit.
// The outbox table still needs published_at for visibility, but the relay logic is replaced by Debezium.
// Debezium handles restarts via Kafka Connect offset storage — it resumes from the last WAL position.

